module control ( opcode, reg_dst, mem_to_reg, alu_op, jump, branch, mem_read, 
        mem_write, alu_src, reg_write, sign_or_zero );
  input [2:0] opcode;
  output [1:0] reg_dst;
  output [1:0] mem_to_reg;
  output [1:0] alu_op;
  output jump, branch, mem_read, mem_write, alu_src, reg_write, sign_or_zero;
  wire   \mem_to_reg[0] , \alu_op[1] , n1, n2, n3, n4, n5, n6, n7;
  assign mem_to_reg[1] = reg_dst[1];
  assign mem_read = \mem_to_reg[0] ;
  assign mem_to_reg[0] = \mem_to_reg[0] ;
  assign alu_src = \alu_op[1] ;
  assign alu_op[1] = \alu_op[1] ;

  NAND2X0 U3 ( .IN1(opcode[0]), .IN2(n1), .QN(sign_or_zero) );
  NAND2X0 U4 ( .IN1(n2), .IN2(n3), .QN(reg_write) );
  INVX0 U5 ( .INP(n4), .ZN(n3) );
  AOI21X1 U6 ( .IN1(n5), .IN2(n6), .IN3(reg_dst[1]), .QN(n2) );
  AND2X1 U7 ( .IN1(n7), .IN2(n1), .Q(reg_dst[0]) );
  NOR2X0 U8 ( .IN1(opcode[1]), .IN2(opcode[2]), .QN(n1) );
  NOR3X0 U9 ( .IN1(opcode[2]), .IN2(n7), .IN3(n6), .QN(reg_dst[1]) );
  NOR2X0 U10 ( .IN1(opcode[2]), .IN2(n6), .QN(jump) );
  AO21X1 U11 ( .IN1(opcode[0]), .IN2(n6), .IN3(n4), .Q(\alu_op[1] ) );
  OR3X1 U12 ( .IN1(branch), .IN2(mem_write), .IN3(n4), .Q(alu_op[0]) );
  AO21X1 U13 ( .IN1(branch), .IN2(opcode[0]), .IN3(\mem_to_reg[0] ), .Q(n4) );
  NOR3X0 U14 ( .IN1(opcode[1]), .IN2(opcode[0]), .IN3(n5), .QN(\mem_to_reg[0] ) );
  NOR3X0 U15 ( .IN1(opcode[1]), .IN2(n7), .IN3(n5), .QN(mem_write) );
  INVX0 U16 ( .INP(opcode[0]), .ZN(n7) );
  NOR2X0 U17 ( .IN1(n5), .IN2(n6), .QN(branch) );
  INVX0 U18 ( .INP(opcode[1]), .ZN(n6) );
  INVX0 U19 ( .INP(opcode[2]), .ZN(n5) );
endmodule


